public class Demo extends Application {
  @Override
  public void start(Stage stage) {
    var root = new StackPane(new Label("Bonjour !"));
    stage.setScene(new Scene(root, 640, 400));
    stage.setTitle("Ma première fenêtre");
    stage.show();
  }
}

var champ = new TextField();
var bouton = new Button("Ajouter");
var ligne = new HBox(12, champ, bouton);
ligne.setPadding(new Insets(16));
HBox.setHgrow(champ, Priority.ALWAYS);

bouton.setOnAction(event -> {
  message.setText("Bonjour " + nom.getText());
});
champ.addEventFilter(KeyEvent.KEY_PRESSED, event -> {
  if (event.getCode() == KeyCode.ESCAPE) {
    champ.clear();
    event.consume();
  }
});

StringProperty nom = new SimpleStringProperty("");
champ.textProperty().bindBidirectional(nom);
message.textProperty().bind(nom.concat(" apprend JavaFX"));
bouton.disableProperty().bind(nom.isEmpty());

public class FormController {
  @FXML private TextField nom;
  @FXML private Label resultat;

  @FXML private void initialize() {
    resultat.textProperty().bind(nom.textProperty());
  }
}

Task<String> task = new Task<>() {
  @Override protected String call() throws Exception {
    return chargerDonnees();
  }
};
task.setOnSucceeded(e -> label.setText(task.getValue()));
task.setOnFailed(e -> label.setText("Chargement impossible"));
Thread worker = new Thread(task);
worker.setDaemon(true);
worker.start();
